기존 환율 목록 화면(FX_LIST_10)의 업무 JS 야.

```js
page.init({
  data: { list: [] },
  action: {
    "FX_RATE_LIST": {
      params: function () {
        return { baseDate: fw.today() };
      },
      scb: function (res) {
        debugger;
        var rows = res.list;
        var html = "";
        for (var i = 0; i < rows.length; i++) {
          html += "<li class='rate' data-cur='" + rows[i].cur + "'>" + rows[i].name + " " + rows[i].baseRate + "</li>";
        }
        $("#rateList").html(html);
      },
      ecb: function (err) {
        console.log(err);
      }
    }
  },
  init: function () {
    fw.ajax("FX_RATE_LIST");
  },
  event: function () {
    $("#rateList").on("click", ".rate", function () {
      fw.move("FX_DETAIL_10", { cur: $(this).data("cur") });
    });
  }
});
```

규약 위반과 결함을 항목별로 짚어 줘. 코드는 아직 고치지 마.
